'use client';
import {useState} from 'react';import{request}from'../../lib/api';
export default function ImagePicker({token,onUploaded}:{token:string;onUploaded:(url:string)=>void}){const[busy,setBusy]=useState(false);const[message,setMessage]=useState('');async function upload(file:File){try{setBusy(true);const body=new FormData();body.append('file',file);const result=await request<{url:string}>('/api/vendor/uploads',{method:'POST',body},token);onUploaded('http://localhost:8080'+result.url);setMessage('Image ready');}catch(e:any){setMessage(e.message)}finally{setBusy(false)}}return <label className="tap block cursor-pointer rounded-xl border-2 border-dashed border-stone-300 bg-white px-4 py-3 text-center text-xs font-bold">{busy?'UPLOADING…':message||'UPLOAD ITEM IMAGE'}<input type="file" accept="image/*" className="hidden" onChange={e=>e.target.files?.[0]&&upload(e.target.files[0])}/></label>}
